// 话题讨论 (discussion) data API — separate from the flashcard/texts/grammar modules.
// Discussion data lives in src/data/discussion/{series}-{unit}.json (generated by
// scripts/convert_discussion.py) and is lazy-loaded, one chunk per unit.
// The glob pattern requires a dash so discussion/meta.json is excluded.

import meta from "./discussion/meta.json"; // { "hsk-1": { lessonCount, textCount, questionCount }, ... }

const loaders = import.meta.glob("./discussion/*-*.json");

function key(seriesId, unitId) {
  return `${seriesId}-${unitId}`;
}

export function hasDiscussion(seriesId, unitId) {
  return !!meta[key(seriesId, unitId)];
}

const _cache = new Map();
export function loadDiscussionUnit(seriesId, unitId) {
  const k = key(seriesId, unitId);
  if (_cache.has(k)) return _cache.get(k);
  const loader = loaders[`./discussion/${k}.json`];
  const p = loader ? loader().then((m) => m.default) : Promise.resolve(null);
  _cache.set(k, p);
  return p;
}

export async function getDiscussionLesson(seriesId, unitId, lessonNum) {
  const ds = await loadDiscussionUnit(seriesId, unitId);
  if (!ds) return null;
  return ds.lessons.find((l) => l.num === Number(lessonNum)) || null;
}
